exercises.solution:
const result = document.querySelector('#result');

async function render(name) {
  try {
    const user = await fakeApi(name);
    result.textContent = user.name + ' — ' + user.role;
  } catch (error) {
    result.textContent = 'Ошибка: ' + error.message;
  }
}

render('Аня');
